{"path": "forth.py", "content": "class StackUnderflowError(Exception):
    """Exception raised when the stack has too few items for an operation.

    message: explanation of the error.
    """

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    return token.isdigit() or (token[:1] == "-" and token[1:].isdigit())


def _pop(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")
    values = stack[-count:]
    del stack[-count:]
    return values


def _add(stack):
    a, b = _pop(stack, 2)
    stack.append(a + b)


def _sub(stack):
    a, b = _pop(stack, 2)
    stack.append(a - b)


def _mul(stack):
    a, b = _pop(stack, 2)
    stack.append(a * b)


def _div(stack):
    a, b = _pop(stack, 2)
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    stack.append(quotient if (a < 0) == (b < 0) else -quotient)


def _dup(stack):
    (a,) = _pop(stack, 1)
    stack.extend((a, a))


def _drop(stack):
    _pop(stack, 1)


def _swap(stack):
    a, b = _pop(stack, 2)
    stack.extend((b, a))


def _over(stack):
    a, b = _pop(stack, 2)
    stack.extend((a, b, a))


_BUILTINS = {
    "+": _add,
    "-": _sub,
    "*": _mul,
    "/": _div,
    "dup": _dup,
    "drop": _drop,
    "swap": _swap,
    "over": _over,
}


def evaluate(input_data):
    """Evaluate a list of Forth source lines and return the resulting stack."""
    # Each word maps to a list of primitive actions: builtin callables or ints.
    words = {name: [func] for name, func in _BUILTINS.items()}
    stack = []

    tokens = [tok.lower() for line in input_data for tok in line.split()]
    index = 0
    while index < len(tokens):
        token = tokens[index]
        index += 1

        if token == ":":
            try:
                end = tokens.index(";", index)
            except ValueError:
                raise ValueError("undefined operation") from None
            if end == index:
                raise ValueError("undefined operation")
            name, body = tokens[index], tokens[index + 1:end]
            if _is_number(name):
                raise ValueError("illegal operation")
            expansion = []
            for item in body:
                if item in words:
                    expansion.extend(words[item])
                elif _is_number(item):
                    expansion.append(int(item))
                else:
                    raise ValueError("undefined operation")
            words[name] = expansion
            index = end + 1
        elif token in words:
            for action in words[token]:
                if isinstance(action, int):
                    stack.append(action)
                else:
                    action(stack)
        elif _is_number(token):
            stack.append(int(token))
        else:
            raise ValueError("undefined operation")

    return stack
